import dlabad = require( './index' );


// TESTS //

// The function returns void...
{
	dlabad( new Float64Array( 1 ), new Float64Array( 1 ) ); // $ExpectType void
}

// The compiler throws an error if the function is provided a first argument which is not a Float64Array...
{
	dlabad( 5, new Float64Array( 1 ) ); // $ExpectError
	dlabad( true, new Float64Array( 1 ) ); // $ExpectError
	dlabad( false, new Float64Array( 1 ) ); // $ExpectError
	dlabad( null, new Float64Array( 1 ) ); // $ExpectError
	dlabad( undefined, new Float64Array( 1 ) ); // $ExpectError
	dlabad( [], new Float64Array( 1 ) ); // $ExpectError
	dlabad( {}, new Float64Array( 1 ) ); // $ExpectError
	dlabad( ( x: number ): number => x, new Float64Array( 1 ) ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a Float64Array...
{
	dlabad( new Float64Array( 1 ), 5 ); // $ExpectError
	dlabad( new Float64Array( 1 ), true ); // $ExpectError
	dlabad( new Float64Array( 1 ), false ); // $ExpectError
	dlabad( new Float64Array( 1 ), null ); // $ExpectError
	dlabad( new Float64Array( 1 ), undefined ); // $ExpectError
	dlabad( new Float64Array( 1 ), [] ); // $ExpectError
	dlabad( new Float64Array( 1 ), {} ); // $ExpectError
	dlabad( new Float64Array( 1 ), ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	dlabad(); // $ExpectError
	dlabad( new Float64Array( 1 ) ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns void...
{
	dlabad.ndarray( new Float64Array( 1 ), 0, new Float64Array( 1 ), 0 ); // $ExpectType void
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a Float64Array...
{
	dlabad.ndarray( 5, 0, new Float64Array( 1 ), 0 ); // $ExpectError
	dlabad.ndarray( true, 0, new Float64Array( 1 ), 0 ); // $ExpectError
	dlabad.ndarray( false, 0, new Float64Array( 1 ), 0 ); // $ExpectError
	dlabad.ndarray( null, 0, new Float64Array( 1 ), 0 ); // $ExpectError
	dlabad.ndarray( undefined, 0, new Float64Array( 1 ), 0 ); // $ExpectError
	dlabad.ndarray( [], 0, new Float64Array( 1 ), 0 ); // $ExpectError
	dlabad.ndarray( {}, 0, new Float64Array( 1 ), 0 ); // $ExpectError
	dlabad.ndarray( ( x: number ): number => x, 0, new Float64Array( 1 ), 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a number...
{
	dlabad.ndarray( new Float64Array( 1 ), true, new Float64Array( 1 ), 0 ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), false, new Float64Array( 1 ), 0 ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), null, new Float64Array( 1 ), 0 ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), undefined, new Float64Array( 1 ), 0 ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), '5', new Float64Array( 1 ), 0 ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), [], new Float64Array( 1 ), 0 ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), {}, new Float64Array( 1 ), 0 ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), ( x: number ): number => x, new Float64Array( 1 ), 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a Float64Array...
{
	dlabad.ndarray( new Float64Array( 1 ), 0, 5, 0 ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0, true, 0 ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0, false, 0 ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0, null, 0 ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0, undefined, 0 ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0, [], 0 ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0, {}, 0 ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	dlabad.ndarray( new Float64Array( 1 ), 0, new Float64Array( 1 ), true ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0, new Float64Array( 1 ), false ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0, new Float64Array( 1 ), null ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0, new Float64Array( 1 ), undefined ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0, new Float64Array( 1 ), '5' ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0, new Float64Array( 1 ), [] ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0, new Float64Array( 1 ), {} ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0, new Float64Array( 1 ), ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	dlabad.ndarray(); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ) ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0 ); // $ExpectError
	dlabad.ndarray( new Float64Array( 1 ), 0, new Float64Array( 1 ) ); // $ExpectError
}
